using System.Text;
using System.Text.Json;
internal static class LibraryAcceptIdentityTests {
 internal static async Task Run(){
  var root=Path.Combine(Path.GetTempPath(),"LibraryAcceptIdentity-"+Guid.NewGuid().ToString("N"));var h=new SimAssemblyHeader("01PART                ","fixture","V1.2","PART                ","PART","A","202020","A",false);var key=h.SourceKeyRaw;var store=new SimLibraryBomStore(root,()=>[h]);var actor=new SimPersona("fixture","fixture","Fixture","ACTIVE",[],[],true,"fixture");var viewer=new SimPersona("viewer","viewer","Viewer","ACTIVE",[],["assembly_library.view"],false,"fixture");
  void Check(bool x,string m){if(!x)throw new Exception(m);}async Task Reject(Func<Task> f){try{await f();}catch(Exception e)when(e is SimRfqIntakeProblem or LibraryBomPermissionException){return;}throw new Exception("Expected identity rejection");}
  var v=await store.Get(key,actor);v=await store.Change(new(key,v.Token,"START"),actor);var txt=string.Join('\t',SimVproParser.Headers)+"\tDRAW#=PART REV A\n001\t929647-04-02-ND\tOPTIONAL\t\t10\t.0001\tEA\t1\t0\t0\t0\tP\t\n002\t\t(NOB) J2\t\t0\t0\t\t0\t0\t0\t0\t\t\n";v=await store.Change(new(key,v.Token,"IMPORT",FileName:"nob.txt",TextBase64:Convert.ToBase64String(Encoding.ASCII.GetBytes(txt))),actor);var r=v.Record.Draft!.Rows[0];
  var row=new LibraryRowEdit(r.Id,r.Find,r.SourcePartNumber,r.Description,"0","EA",r.ReferenceDesignators,"MFG","","",false,false,"",false);
  LibraryBomCommand Cmd(string action,string token,LibraryRowEdit[] rows)=>new(key,token,action,DrawingRevision:"A",BomRevision:"A",QuantityBasis:"PER_ASSEMBLY",Rows:rows,RowId:r.Id);
  v=await store.Change(Cmd("SAVE",v.Token,[row]),actor);Check(!v.Record.Draft!.Rows[0].IdentityConfirmed&&v.Record.Draft.Rows[0].ManufacturerPartNumber==""&&v.Record.Draft.Rows[0].Acceptance is null,"classification/save is not acceptance");var stale=v.Token;v=await store.Change(Cmd("ACCEPT_ROW",v.Token,[row]),actor);var accepted=v.Record.Draft!.Rows[0];Check(accepted.IdentityConfirmed&&accepted.ManufacturerPartNumber==r.SourcePartNumber&&accepted.Acceptance is not null&&accepted.ManufacturerName=="","Accept reuses exact source, no name invention");Check(v.Record.History.Last().Action=="ACCEPT_ROW"&&v.Record.History.Last().Actor.Id==actor.Id,"decision attribution");Check((await new SimLibraryBomStore(root,()=>[h]).Get(key,actor)).Token==v.Token,"reopen persistence");await Reject(async()=>await store.Change(Cmd("ACCEPT_ROW",stale,[row]),actor));await Reject(async()=>await store.Change(Cmd("ACCEPT_ROW",v.Token,[row]),viewer));
  row=row with{ManufacturerPartNumber=r.SourcePartNumber,IdentityConfirmed=true};v=await store.Change(Cmd("EDIT_ROW",v.Token,[row]),actor);Check(v.Record.Draft!.Rows[0].Acceptance is null,"Edit unlocks");var token=v.Token;await Reject(async()=>await store.Change(Cmd("ACCEPT_ROW",token,[row with{SourcePartNumber="",ManufacturerPartNumber=""}]),actor));await Reject(async()=>await store.Change(Cmd("ACCEPT_ROW",token,[row with{IdentityBasis="UNRESOLVED",IdentityConfirmed=false}]),actor));await Reject(async()=>await store.Change(Cmd("ACCEPT_ROW",token,[row with{IdentityBasis="INTERNAL_UNKNOWN",IdentityConfirmed=false}]),actor));Check((await store.Get(key,actor)).Token==token,"invalid identity atomic");
  var neighbor=new LibraryRowEdit(Guid.NewGuid().ToString(),"2","SECOND","Ordinary","2","EA","R2","CUSTOMER","","",false,false,"",false);row=row with{ManufacturerPartNumber="EXPLICIT-MPN",IdentityConfirmed=false};v=await store.Change(Cmd("ACCEPT_ROW",v.Token,[row,neighbor]),actor);Check(v.Record.Draft!.Rows[0].ManufacturerPartNumber=="EXPLICIT-MPN","explicit different entry preserved rather than overwritten");Check(!v.Record.Draft.Rows[1].IdentityConfirmed&&v.Record.Draft.Rows[1].Acceptance is null,"neighbor not confirmed");
  v=await store.Change(Cmd("ACCEPT_ROW",v.Token,[row,neighbor]) with{RowId=neighbor.Id},actor);Check(v.Record.Draft!.Rows[1].IdentityConfirmed&&v.Record.Draft.Rows[1].Quantity=="2","ordinary customer identity accepted without manufacturer invention");
  // Multiple alternatives still require their decisions and explicit primary choice.
  v=await store.Change(new(key,v.Token,"ALTERNATE",RowId:neighbor.Id,AlternateDecision:"ADD",PartNumber:"ALT-A"),actor);v=await store.Change(new(key,v.Token,"ALTERNATE",RowId:neighbor.Id,AlternateDecision:"ADD",PartNumber:"ALT-B"),actor);await Reject(async()=>await store.Change(Cmd("ACCEPT_ROW",v.Token,[row,neighbor]) with{RowId=neighbor.Id},actor));Check(v.Record.Draft!.Rows[1].Alternates.All(a=>a.Status=="PROPOSED")&&v.Record.Draft.Rows[1].SelectedAlternateId is null,"Accept cannot approve/select alternatives");
  Check(v.Record.Reviews.Length==0&&v.Record.SourceVersions is null&&v.Record.Draft.EvidenceHash==SimLibraryBomStore.Hash(Encoding.ASCII.GetBytes(txt)),"history/source/final approval untouched");
  Console.WriteLine("PASS Accept confirms explicit identity: exact source MPN reuse, explicit override retained, draft save not confirmation, zero NOB and ordinary quantity, edit/reload, neighbor preservation, missing/unknown identity, stale/viewer guards and no alternate/final approval.");
 }
}
